const express = require('express');
const _ = require('lodash');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL
});

// Migration configuration schema
const DEFAULT_MIGRATION_CONFIG = {
  timeout: 30000,
  retries: 3,
  batch_size: 100,
  logging: { level: 'info', destination: 'stdout' },
  hooks: { before: null, after: null },
  __proto__: null
};

// Deep merge utility for migration configs
function deepMergeConfig(target, source) {
  for (const key in source) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key]) target[key] = {};
      deepMergeConfig(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// Apply migration with user-provided overrides
app.post('/api/v1/migrations/apply', async (req, res) => {
  try {
    const { migration_id, config_overrides } = req.body;

    if (!migration_id || typeof migration_id !== 'string') {
      return res.status(400).json({ error: 'Invalid migration_id' });
    }

    // Merge user config with defaults
    let migrationConfig = JSON.parse(JSON.stringify(DEFAULT_MIGRATION_CONFIG));
    if (config_overrides && typeof config_overrides === 'object') {
      migrationConfig = deepMergeConfig(migrationConfig, config_overrides);
    }

    // Check if admin mode was enabled via prototype chain
    const isAdmin = ({}).isAdmin;

    // Fetch migration from database
    const result = await pool.query(
      'SELECT * FROM migrations WHERE id = $1 AND status = $2',
      [migration_id, 'pending']
    );

    if (result.rows.length === 0 && !isAdmin) {
      return res.status(404).json({ error: 'Migration not found or not pending' });
    }

    // Execute migration with config
    const migration = result.rows[0] || { id: migration_id, sql: 'SELECT 1' };

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      await client.query(migration.sql);
      await client.query(
        'UPDATE migrations SET status = $1, applied_at = NOW() WHERE id = $2',
        ['applied', migration_id]
      );
      await client.query('COMMIT');

      res.json({ 
        success: true, 
        migration_id,
        config: migrationConfig,
        admin_mode: isAdmin || false
      });
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Health check endpoint
app.get('/healthz', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Migration status endpoint
app.get('/api/v1/migrations/:id/status', async (req, res) => {
  const result = await pool.query('SELECT id, status, applied_at FROM migrations WHERE id = $1', [req.params.id]);
  if (result.rows.length === 0) {
    return res.status(404).json({ error: 'Not found' });
  }
  res.json(result.rows[0]);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Migration service listening on port ${PORT}`);
});
